import { Button, Slider } from "@mui/material";
import React, { useEffect, useState } from "react";
import { Dropdown } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import jsondata from "../json/interrogartive_sentence.json";
import "../style/level2.css";
import arrayShuffle from "array-shuffle";
import Table from "react-bootstrap/Table";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import Swal from "sweetalert2";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";

function Level2() {
  let [flag1, setFlag1] = useState(false);

  let [ArrIndex, setArrIndex] = useState(1);
  var [mainArr, setmainArr] = useState([]);
  var [currentquearr, setCurrentquearr] = useState([]);
  var [currentquetagarr, setCurrentquetagarr] = useState([]);
  var [currentoparr, setCurrentoparr] = useState([]);
  var [currentfeedbackarr, setCurrentfeedbackarr] = useState([]);
  var [currcompletesentence, setCurrcompletesentence] = useState([]);
  var [score, setScore] = useState(0);

  var [dropval1, setDropval1] = useState("_______");
  var [dropval2, setDropval2] = useState("_______");
  var [dropval3, setDropval3] = useState("_______");

  var [canDrop, setCanDrop] = useState(false);
  var [canDrop1, setCanDrop1] = useState(false);
  var [canDrop2, setCanDrop2] = useState(false);

  var [check1, setCheck1] = useState(false);
  var [check2, setCheck2] = useState(false);
  var [check3, setCheck3] = useState(false);

  const navigate = useNavigate();
  const { t, i18n } = useTranslation();

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 2 page");

  useEffect(() => {
    if (mainArr.length === 0)
      addToMainArr(arrayShuffle(Object.values(jsondata.level2)));
  }, []);

  const addToMainArr = (arrElement) => {
    setmainArr((prev) => [...prev, ...arrElement]);
  };

  useEffect(() => {
    console.log("mainArr ==> ", mainArr);
    if (mainArr.length !== 0) {
      const currentItem = mainArr[ArrIndex];
      if (currentItem) {
        const shuffledOptions = arrayShuffle(currentItem.options);
        setCurrentoparr(shuffledOptions);

        const tempquesarr1 = currentItem.questions.map((q) => q.question);
        const tempquesarr2 = currentItem.questions.map((q) => q.tag);
        const tempquesarr3 = currentItem.questions.map((q) => q.feedback);
        const tempquesarr4 = currentItem.questions.map(
          (q) => q.question_with_tag
        );

        setCurrentquearr(tempquesarr1);
        setCurrentquetagarr(tempquesarr2);
        setCurrentfeedbackarr(tempquesarr3);
        setCurrcompletesentence(tempquesarr4);
      }
    }
  }, [mainArr, ArrIndex]);

  const handleSelchange = () => {
    navigate("/launchpage/englishactivity/interrogativesentences/level1");

    ReactGA.event({
      action:
        "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Levels dropdown button",
      category:
        "English CDAC-OlabsNxtG-En-24 | level-2 Levels dropdown button clicked",
      label:
        "English CDAC-OlabsNxtG-En-24 | level-2 Levels dropdown button clicked to navigate to level 1.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-2 "Levels" button',
      "Clicked",
      'Level-2 "Levels" dropdown button to navigate to level 1.'
    );
  };

  const handleOndrop1 = (e) => {
    dropval1 = e.dragData;
    setDropval1(dropval1);

    if (dropval1 == currentquetagarr[0]) {
      document.getElementById("drag1").style.background = "#32a852";
      canDrop = true;
      setCanDrop(canDrop);
      setCheck1(true);

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on first blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on first blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on first blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "First blank field",
        "Dropped",
        "Dropped in first blank field of level 2",
        [{ input: dropval1, answer: currentquetagarr[0], result: "correct" }]
      );
    } else {
      document.getElementById("drag1").style.background = "#FF3131";
      Swal.fire({
        title: "Incorrect!",
        html: `
        <p><b>"${dropval1}"</b> is not the correct tag.</p>
        <p>Given sentence is an "<strong><em>${currentfeedbackarr[0]}</em></strong>". Use the question tag according to ${currentfeedbackarr[0]}.</p>
      `,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on first blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on first blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on first blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "First blank field",
        "Dropped",
        "Dropped in first blank field of level 2",
        [{ input: dropval1, answer: currentquetagarr[0], result: "incorrect" }]
      );
    }
  };

  const handleOndrop2 = (e) => {
    dropval2 = e.dragData;
    setDropval2(dropval2);

    if (dropval2 == currentquetagarr[1]) {
      document.getElementById("drag2").style.background = "#32a852";
      canDrop1 = true;
      setCanDrop1(canDrop1);
      setCheck2(true);

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on second blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on second blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on second blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Second blank field",
        "Dropped",
        "Dropped in second blank field of level 2",
        [{ input: dropval2, answer: currentquetagarr[1], result: "correct" }]
      );
    } else {
      document.getElementById("drag2").style.background = "#FF3131";
      Swal.fire({
        title: "Incorrect!",
        html: `
          <p><b>"${dropval2}"</b> is not the correct tag.</p>
          <p>Given sentence is an "<strong><em>${currentfeedbackarr[1]}</em></strong>". Use the question tag according to ${currentfeedbackarr[1]}.</p>
        `,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on second blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on second blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on second blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Second blank field",
        "Dropped",
        "Dropped in second blank field of level 2",
        [{ input: dropval2, answer: currentquetagarr[1], result: "incorrect" }]
      );
    }
  };

  const handleOndrop3 = (e) => {
    dropval3 = e.dragData;
    setDropval3(dropval3);

    if (dropval3 == currentquetagarr[2]) {
      document.getElementById("drag3").style.background = "#32a852";
      canDrop2 = true;
      setCanDrop2(canDrop2);
      setCheck3(true);

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on third blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on third blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on third blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Third blank field",
        "Dropped",
        "Dropped in third blank field of level 2",
        [{ input: dropval3, answer: currentquetagarr[2], result: "correct" }]
      );
    } else {
      document.getElementById("drag3").style.background = "#FF3131";
      Swal.fire({
        title: "Incorrect!",
        html: `
        <p><b>"${dropval3}"</b> is not the correct tag.</p>
        <p>Given sentence is an "<strong><em>${currentfeedbackarr[2]}</em></strong>". Use the question tag according to ${currentfeedbackarr[2]}.</p>
      `,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Dropped on third blank space.",
        category:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on third blank space.",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Dropped on third blank space.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        "Third blank field",
        "Dropped",
        "Dropped in third blank field of level 2",
        [{ input: dropval3, answer: currentquetagarr[2], result: "incorrect" }]
      );
    }
  };

  const handlenextbtn = () => {
    ArrIndex = ArrIndex + 1;
    setArrIndex(ArrIndex);

    if (ArrIndex <= mainArr.length - 1) {
      setDropval1("______");
      setDropval2("______");
      setDropval3("______");
      setCheck1(false);
      setCheck2(false);
      setCheck3(false);
      canDrop = false;
      setCanDrop(canDrop);
      canDrop1 = false;
      setCanDrop1(canDrop1);
      canDrop2 = false;
      setCanDrop2(canDrop2);

      score = score + 1;
      setScore(score);

      document.getElementById("drag1").style.backgroundColor = "#FFFFFF";
      document.getElementById("drag2").style.backgroundColor = "#FFFFFF";
      document.getElementById("drag3").style.backgroundColor = "#FFFFFF";

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-24 | level-2 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Next button clicked for set of next sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Next" button',
        "Clicked",
        'Level-2 "Next" button for set of next sentence.'
      );
    } else {
      setTimeout(() => {
        setFlag1(true);
      }, 500);

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-24 | level-2 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Next button clicked and all sentences are completed.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Next" button',
        "Clicked",
        'Level-2 "Next" button clicked and all sentences are completed.'
      );
    }
  };

  const handleskipbtn = () => {
    ArrIndex = ArrIndex + 1;
    setArrIndex(ArrIndex);

    if (ArrIndex <= mainArr.length - 1) {
      setDropval1("______");
      setDropval2("______");
      setDropval3("______");
      setCheck1(false);
      setCheck2(false);
      setCheck3(false);
      canDrop = false;
      setCanDrop(canDrop);
      canDrop1 = false;
      setCanDrop1(canDrop1);
      canDrop2 = false;
      setCanDrop2(canDrop2);

      document.getElementById("drag1").style.backgroundColor = "#FFFFFF";
      document.getElementById("drag2").style.backgroundColor = "#FFFFFF";
      document.getElementById("drag3").style.backgroundColor = "#FFFFFF";

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-24 | level-2 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Skip button clicked for set of next sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Skip" button',
        "Clicked",
        'Level-2 "Skip" button for set of next sentence.'
      );
    } else {
      setTimeout(() => {
        setFlag1(true);
      }, 500);

      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-24 | level-2 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-2 Skip button clicked and all sentences are completed.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Skip" button',
        "Clicked",
        'Level-2 "Skip" button clicked and all sentences are completed.'
      );
    }
  };

  const handlerestartbtn = () => {
    ReactGA.event({
      action:
        "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Restart button",
      category: "English CDAC-OlabsNxtG-En-24 | level-2 Restart button clicked",
      label:
        "English CDAC-OlabsNxtG-En-24 | level-2 Restart button clicked for reattempt the level2.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-2 "Restart" button',
      "Clicked",
      'Level-2 "Restart" button for reattempt the level2.'
    );

    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag1 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>Question Tag</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  {t("levels")}
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item onClick={handleSelchange}>
                    {t("level_1")}
                  </Dropdown.Item>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    {t("level_2")}
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-4 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  background: "linear-gradient(#ADD8E6, #9198e5)",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have attempted {score + 1} out of {mainArr.length}{" "}
                  sentences sets.
                </p>
                <div>
                  <Button variant="contained" onClick={handlerestartbtn}>
                    Restart
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>Question Tag</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  Levels
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item onClick={handleSelchange}>
                    Level 1
                  </Dropdown.Item>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    Level 2
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "27px" }}
            >
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={0}
                step={1}
                min={0}
                max={5}
                value={ArrIndex}
                onChange={(e, newValue) => setArrIndex(newValue)}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {ArrIndex}/5
              </span>
            </div>

            <div className="">
              <Table striped responsive className="table-striped">
                <tbody>
                  <tr
                    className="row-border"
                    style={{ backgroundColor: "#d98b19" }}
                  >
                    <th>Sentence</th>
                    <th>Question tag</th>
                  </tr>
                  <tr className="row-border">
                    <td className="normal_row" style={{ cursor: "pointer" }}>
                      {currentquearr[0]}
                    </td>
                    <td>
                      {!canDrop ? (
                        <DropTarget
                          targetKey=""
                          onHit={(e) => handleOndrop1(e)}
                        >
                          <div className="drop-target" id="drag1">
                            {dropval1}
                          </div>
                        </DropTarget>
                      ) : (
                        <DropTarget targetKey="">
                          <div className="drop-target" id="drag1">
                            {dropval1}
                          </div>
                        </DropTarget>
                      )}
                    </td>
                  </tr>
                  <tr className="row-border">
                    <td className="normal_row" style={{ cursor: "pointer" }}>
                      {currentquearr[1]}
                    </td>
                    <td>
                      {!canDrop1 ? (
                        <DropTarget
                          targetKey=""
                          onHit={(e) => handleOndrop2(e)}
                        >
                          <div className="drop-target" id="drag2">
                            {dropval2}
                          </div>
                        </DropTarget>
                      ) : (
                        <DropTarget targetKey="">
                          <div className="drop-target" id="drag2">
                            {dropval2}
                          </div>
                        </DropTarget>
                      )}
                    </td>
                  </tr>
                  <tr>
                    <td className="normal_row" style={{ cursor: "pointer" }}>
                      {currentquearr[2]}
                    </td>
                    <td>
                      {!canDrop2 ? (
                        <DropTarget
                          targetKey=""
                          onHit={(e) => handleOndrop3(e)}
                        >
                          <div className="drop-target" id="drag3">
                            {dropval3}
                          </div>
                        </DropTarget>
                      ) : (
                        <DropTarget targetKey="">
                          <div className="drop-target" id="drag3">
                            {dropval3}
                          </div>
                        </DropTarget>
                      )}
                    </td>
                  </tr>
                </tbody>
              </Table>
            </div>

            <div
              className="d-flex justify-content-around mt-5"
              style={{
                background:
                  "transparent linear-gradient(268deg, #FDBD23 0%, #F7B94E 100%) 0% 0% no-repeat padding-box",
                borderRadius: "10px",
                boxShadow: "0px 3px 6px #00000029",
                color: "#000000",
                opacity: "1",
                padding: "2%",
                fontWeight: "bolder",
              }}
            >
              {currentoparr.map((item, idx1) => (
                <div
                  className=""
                  style={{
                    border: "1px solid black",
                    borderRadius: "5px",
                    padding: "0.5vh 0.5vh 0.5vh 0.5vh",
                    background: "#FEF1B5",
                    cursor: "grab",
                  }}
                >
                  <DragDropContainer targetKey="" key={item} dragData={item}>
                    <span style={{ cursor: "grab" }}>{item}</span>
                  </DragDropContainer>
                </div>
              ))}
            </div>

            <div className="mt-5 d-flex justify-content-around">
              {check1 && check2 && check3 == true ? (
                <Button variant="contained" disabled>
                  {t("skip")}
                </Button>
              ) : (
                <Button variant="contained" onClick={handleskipbtn}>
                  {t("skip")}
                </Button>
              )}

              {check1 && check2 && check3 == true ? (
                <Button variant="contained" onClick={handlenextbtn}>
                  {t("next")}
                </Button>
              ) : (
                <Button variant="contained" disabled>
                  {t("next")}
                </Button>
              )}
            </div>

            <div className="d-flex justify-content-center align-items-center">
              {check1 && check2 && check3 == true ? (
                <div
                  className={`mt-3 text-center p-3 
                `}
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "#ffffff",
                    boxShadow: "0px 0px 10px rgba(0, 0, 0, 0.5)",
                    borderRadius: "50px",
                    padding: "2%",
                    fontWeight: "bolder",
                  }}
                >
                  <span style={{ color: "green" }}>
                    {currcompletesentence[0]}
                  </span>
                 <br></br>
                  <span style={{ color: "green" }}>
                    {currcompletesentence[1]}
                  </span>
                  <br></br>
                  <span style={{ color: "green" }}>
                    {currcompletesentence[2]}
                  </span><br></br>
                  are a complete sentences with question tag.
                </div>
              ) : (
                <></>
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_2_1")}</li>
                <li>{t("instruction_2_2")}</li>
                <li>{t("instruction_2_3")}</li>
                <li>{t("instruction_2_4")}</li>
                <li>{t("instruction_2_5")}</li>
                <li>{t("instruction_2_6")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Level2;
